#!/usr/bin/env python3
"""Compile the two shaders with glslc and write src/triangle_spv.hpp (committed, so the
prototype builds on Windows without a shader compiler). Run from spike/qt-vulkan/."""
import pathlib
import struct
import subprocess
import sys
import tempfile

here = pathlib.Path(__file__).resolve().parent
out = ["// SPDX-License-Identifier: Apache-2.0",
       "// Generated by shaders/embed_spv.py from shaders/triangle.{vert,frag}; do not edit.",
       "#pragma once", "#include <cstdint>", ""]
with tempfile.TemporaryDirectory() as tmp:
    for name, src in (("triangle_vert_spv", "triangle.vert"), ("triangle_frag_spv", "triangle.frag")):
        spv = pathlib.Path(tmp) / (src + ".spv")
        subprocess.run(["glslc", "--target-env=vulkan1.3", "-O", str(here / src), "-o", str(spv)],
                       check=True)
        b = spv.read_bytes()
        words = struct.unpack(f"<{len(b) // 4}I", b)
        out.append(f"inline constexpr uint32_t {name}[] = {{")
        for i in range(0, len(words), 8):
            out.append("    " + ", ".join(f"0x{w:08x}u" for w in words[i:i + 8]) + ",")
        out.append("};")
        out.append("")
(here.parent / "src" / "triangle_spv.hpp").write_text("\n".join(out))
sys.exit(0)
